// Function to perform run-length encoding on a string
function rle(input) {
    if (typeof input !== 'string') {
        throw new Error('Input must be a string');
    }

    let encoded = '';
    let count = 1;

    for (let i = 1; i < input.length; i++) {
        if (input[i] === input[i - 1]) {
            count++;
        } else {
            encoded += input[i - 1] + count;
            count = 1;
        }
    }

    // Add the last character and its count
    encoded += input[input.length - 1] + count;

    return encoded;
}

// Main block to test the rle function with sample input data
try {
    const inputString = 'AABBBCCCC';
    const result = rle(inputString);
    console.log(result); // Output: A2B3C4
} catch (error) {
    console.error('Error:', error.message);
}

# Bubble Sort Function in Python

def bubble_sort(arr):
    n = len(arr)
    # Traverse through all array elements
    for i in range(n):
        # Last i elements are already sorted
        for j in range(0, n-i-1):
            # Traverse the array from 0 to n-i-1
            # Swap if the element found is greater than the next element
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]

# Main block with test data
if __name__ == "__main__":
    # Sample input array
    arr = [64, 34, 25, 12, 22, 11, 90]

    try:
        print("Original array:", arr)

        # Call the bubble_sort function
        bubble_sort(arr)

        print("Sorted array:", arr)
    except Exception as e:
        print(f"An error occurred: {e}")
